void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Adaptive decay based on recent conflict rate
    if (conflicts > 0) {
        double conflict_rate = (double)conflicts / (trail.size() + 1);
        if (conflict_rate > 0.05) {
            inc *= 1.2;
        }
    }

    // Variable aging: reduce activity of older variables
    if (level[var] > 0) {
        double age_factor = 1.0 / (1.0 + 0.01 * conflicts);
        activity[var] *= age_factor;
    }

    // Prevent overflow with smarter scaling
    if (activity[var] > 1e100) {
        double scale = 1e-100;
        for (int i = 1; i <= vars; i++) activity[i] *= scale;
        var_inc *= scale;
    }

    // Update heap if variable is present
    if (vsids.inHeap(var)) vsids.update(var);
}
